"""
Kaggle CPU kernel -- self-contained bundle reproducing code/73's exchangeable-
candidate K-sweep at N_SEEDS=200 (code/98's own local design), moved here only
because the local machine was hitting severe CPU contention (multiple other
heavy jobs running concurrently), not because of any algorithmic issue.

This bundle base64-embeds byte-for-byte copies of the pinned local files:
code/47_selection_multiplicity_sweep.py, code/73_exchangeable_candidate_sweep.py,
code/sanity_checks.py, and two static reference result JSONs
(results/selection_multiplicity_sweep.json, results/k_law_functional_form.json)
that code/73's own main() reads at runtime for its "comparison_to_code47_sweep_A"
section. It recreates the exact repo-relative layout under /kaggle/working so
code/73's own path logic (CODE = Path(__file__).resolve().parent,
ROOT = CODE.parent) resolves identically to the local run, then applies
code/98's own single substitution (N_SEEDS: 30 -> 200) and runs it unmodified.

Nothing about the generative process, protocol, or statistical methodology is
changed here -- only the execution environment (uncontended Kaggle CPU instead
of a locally CPU-contended machine).
"""
import base64
import json
import importlib.util
from pathlib import Path

WORK = Path("/kaggle/working")
(WORK / "code").mkdir(parents=True, exist_ok=True)
(WORK / "results").mkdir(parents=True, exist_ok=True)

_FILES_B64 = {'code/47_selection_multiplicity_sweep.py': '', 'code/57_joint_severity_surface.py': '', 'code/73_exchangeable_candidate_sweep.py': '', 'code/sanity_checks.py': '', 'results/selection_multiplicity_sweep.json': '', 'results/k_law_functional_form.json': ''}

for _relpath, _b64 in _FILES_B64.items():
    _out = WORK / _relpath
    _out.write_bytes(base64.b64decode(_b64))
    print(f"wrote {_out} ({_out.stat().st_size} bytes)", flush=True)

CODE = WORK / "code"
ROOT = WORK

_spec = importlib.util.spec_from_file_location(
    "s73", CODE / "73_exchangeable_candidate_sweep.py")
s73 = importlib.util.module_from_spec(_spec)
_spec.loader.exec_module(s73)

_orig_n_seeds = s73.N_SEEDS
_orig_out_path = s73.OUT_PATH

# The ONLY substitution relative to code/73 (same one code/98 makes locally):
s73.N_SEEDS = 200
s73.OUT_PATH = ROOT / "results" / "exchangeable_candidate_sweep_n200.json"

print(f"=== Kaggle: code/73's exchangeable-candidate sweep at N_SEEDS={s73.N_SEEDS} "
      f"(local code/73 itself ran N_SEEDS={_orig_n_seeds}) ===", flush=True)
print(f"    Writing to {s73.OUT_PATH}\n", flush=True)

s73.main()

with open(s73.OUT_PATH) as f:
    out = json.load(f)

target_effect = out["power"]["code47_gap_at_K45_for_scale"]
mde_new = out["power"]["min_detectable_gap_80pct_power_two_sided_05"]
gap_closed = bool(mde_new <= abs(target_effect)) if target_effect is not None else None

b = out["comparison_to_code47_sweep_A"]["exchangeable_lnK_slope_b"]
b_ci = out["comparison_to_code47_sweep_A"]["exchangeable_lnK_slope_b_ci_95"]
b_excludes_zero = bool(b_ci[0] > 0 or b_ci[1] < 0)
ref_b = out["comparison_to_code47_sweep_A"]["code47_lnK_slope_b"]
ref_b_ci = out["comparison_to_code47_sweep_A"]["code47_lnK_slope_b_ci_95"]

print("\n=== power/verdict summary (N_SEEDS=200, run on Kaggle CPU) ===")
print(f"  MDE at N_SEEDS={s73.N_SEEDS}: {mde_new:+.5f}")
print(f"  target effect (code/47 K=45 epoch gap): {target_effect:+.5f}")
print(f"  MDE <= target effect (power gap closed): {gap_closed}")
print(f"\n  exchangeable ln K slope b = {b:+.5f}  95% CI [{b_ci[0]:+.5f}, {b_ci[1]:+.5f}]")
print(f"  slope CI excludes zero: {b_excludes_zero}")
print(f"  code/47 (epoch-based) headline: b = {ref_b:+.5f}  "
      f"95% CI [{ref_b_ci[0]:+.5f}, {ref_b_ci[1]:+.5f}]")
print(f"\n  VERDICT (N_SEEDS=200): {out['verdict']}")
print(f"  {out['verdict_statement']}")
print(f"\n  runtime_seconds: {out['runtime_seconds']:.1f} "
      f"({out['runtime_seconds']/60:.1f} min)")

out["_n200_power_summary"] = {
    "n_seeds": s73.N_SEEDS,
    "code73_n_seeds_for_contrast": _orig_n_seeds,
    "mde_80pct_power": mde_new,
    "target_effect_code47_K45_gap": target_effect,
    "power_gap_closed": gap_closed,
    "exchangeable_lnK_slope_b": b,
    "exchangeable_lnK_slope_b_ci_95": b_ci,
    "exchangeable_slope_ci_excludes_zero": b_excludes_zero,
    "code47_epoch_lnK_slope_b": ref_b,
    "code47_epoch_lnK_slope_b_ci_95": ref_b_ci,
    "note": (
        "Computed from code/73's own main() output fields at N_SEEDS=200 "
        "instead of 30, run on an uncontended Kaggle CPU kernel after the "
        "local run was hitting severe CPU contention. No new statistical "
        "machinery beyond what code/73 itself already computes."),
}
with open(s73.OUT_PATH, "w") as f:
    json.dump(out, f, indent=2)
print(f"\nSaved: {s73.OUT_PATH}")
